  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In humans, DHPG absolute oral bioavailability from a 500 mg dose was 5.4 ± 1.6%, below the 20% threshold."
    },
    {
      "card_ids": ["C12"],
      "claim": "In fasted volunteers, epanolol 200 mg oral solution had mean absolute bioavailability 7.06 ± 3.15%, below the 20% threshold."
    },
    {
      "card_ids": ["C20"],
      "claim": "In healthy male volunteers, salbutamol tablet absolute bioavailability vs IV was 44%, above the 20% threshold."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C20"],
  "decision_summary": "Direct numeric absolute bioavailability records in humans are predominantly below 20% (5.4–7.9%), supporting a low prediction; one strong positive record (44%) introduces uncertainty.",
  "evidence_gaps": [
    "One high-quality positive record (C20) conflicts with multiple numeric negative records; assay-transfer scores are similar, so residual uncertainty remains.",
    "Molecule 2 includes a record (C16) about SCG that is inconsistent with the salbutamol records; it was discounted.",
    "Some negative evidence is qualitative (C31, C10, C04) and Molecule 7 has a conflicting qualitative 20–30% claim (C34) versus numeric 6.2% records; numeric records were preferred."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C14", "C12"],
  "revision_action": "initial",
  "supportive_card_ids": ["C14", "C12"]
}

